entries[59513] = { ["name"] = "Umarmung des Vampyrs", ["text"] = "60 Meter Reichweite\nKanalisiert (Wirken in 20 sek.)\nVerschlingt die Lebenskraft des Ziels, betäubt es und verursacht 20 Sek. lang alle 2 Sek. 15 Schattenschaden, oder bis Prinz Taldaram 40.000 Schaden erlitten hat. Während des Effekts ist die Heilung des Ziels um 100% verringert." }
