entries[59567] = { ["name"] = "Azurblauer Drache", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren azurblauen Drachen oder gibt ihn wieder frei. Das ist ein Flugreittier.\n\"Bleibt besser höflich, wenn Ihr mit einem wütenden Drachen sprecht.\"\nBeute von:\nAlexstraszas Geschenk\nOrt:\nAuge der Ewigkeit" }
entries[59568] = { ["name"] = "Blaudrache", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren Blaudrachen oder gibt ihn wieder frei. Das ist ein Flugreittier.\n\"Stellt Euch nicht zwischen einen Drachen und seinen Zorn.\"\nBeute von:\nAlexstraszas Geschenk\nOrt:\nAuge der Ewigkeit" }
entries[59569] = { ["name"] = "Bronzedrache", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren Bronzedrachen oder gibt ihn wieder frei. Das ist ein Flugreittier.\n\"Verlorene Zeit kommt niemals zurück. Oh wartet, da ist sie ja. - Chronormu\"\nBeute von:\nEwiger Verderber\nZone:\nDas Ausmerzen von Stratholme" }
entries[59570] = { ["name"] = "Rotdrache", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren Rotdrachen oder gibt ihn wieder frei. Das ist ein Flugreittier.\n\"Ihr solltet nicht auf die Fantasien der Barden hören. Ein Drache würde keiner Fliege etwas zuleide tun, solange er nicht zuerst angegriffen wurde.\"\nVerkäufer:\nCielstrasza\nZone:\nDrachenöde\nDer Wyrmruhpakt - Ehrfürchtig\nKosten:\n2000" }
entries[59571] = { ["name"] = "Zwielichtdrache", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren Zwielichtdrachen oder gibt ihn wieder frei. Das ist ein Flugreittier.\n\"Aber die wichtigste Regel, die Regel, die Ihr niemals vergessen dürft, ist: Egal, wie viel er schreien mag, egal, wie sehr er bettelt, füttert ihn niemals nach Mitternacht.\"\nBeute von:\nSartharion\nOrt:\nDas Obsidiansanktum" }
