entries[59759] = { ["name"] = "Figur - Monarchenkrabbe", ["text"] = "Wirken in 2.5 sek.\nTools: Juwelierswerkzeuge\nReagenzien:\nTitanbarren (2), Monarchentopas (2), Waldsmaragd\nOptionale Reagenzien:\n[] (#49)\nBerufsausbilder:\nJuwelierskunst von Nordend (25)\nKosten:\n1\n\nFigur - Monarchenkrabbe\nWird beim Aufheben gebunden\nEinzigartig anlegbarSchmuck\n+3 Ausdauer\n\nPrismatischer Sockel\nPrismatischer Sockel\nSockelbonus: + 2 Ausdauer\n\nBenutzen: Erhöht das Ausweichen 10 Sek. lang um 23 . (1 Min Abklingzeit)\n28\nBenötigt Juwelierskunst von Nordend\n(25)" }
