entries[59785] = { ["name"] = "Schwarzes Kriegsmammut", ["text"] = "Wirken in 1.5 sek.\nBeschwört ein reitbares schwarzes Kriegsmammut oder gibt es wieder frei.\n\"Diese meist friedfertigen, intelligenten Tiere gehen eine enge Bindung mit ihren Reitern ein, weshalb sie sich im Kampf als treu und furchtlos erweisen.\"\nVerkäufer:\nRitter Dameron\nZone:\nTausendwinter\nKosten:\n15" }
