entries[59791] = { ["name"] = "Wollmammut", ["text"] = "Wirken in 1.5 sek.\nBeschwört ein reitbares Wollmammut oder gibt es wieder frei.\n\"Die Wollmammuts stammen direkt von den Vorvätern der Mammutrasse ab und werden als wilder und ursprünglicher angesehen als ihre kurzhaarigen Verwandten.\"\nVerkäufer:\nMei Francis\nZone:\nKristallsangwald\nKosten:\n10000" }
