entries[59793] = { ["name"] = "Wollmammut", ["text"] = "Wirken in 1.5 sek.\nBeschwört ein reitbares Wollmammut oder gibt es wieder frei.\n\"Diese wilde Mammutrasse wird nicht zum Reiten gezüchtet. Die meisten Wollmammuts werden in der Wildnis gefangen und von ihren Reitern gezähmt, was sie zu leidenschaftlichen und geschickten Reittieren macht.\"\nVerkäufer:\nMei Francis\nZone:\nKristallsangwald\nKosten:\n10000" }
entries[59797] = { ["name"] = "Eismammut", ["text"] = "Wirken in 1.5 sek.\nBeschwört ein reitbares Eismammut oder gibt es wieder frei.\n\"Die Söhne Hodirs glauben, dass die Reiter eines schneeweißen Mammuts vor Erfrierungen und Schneeblindheit geschützt sind.\"\nVerkäufer:\nLillehoff\nZone:\nDie Sturmgipfel\nDie Söhne Hodirs - Respektvoll\nKosten:\n1000" }
