entries[60017] = { ["name"] = "Blutdurst", ["text"] = "Nahkampfreichweite\nSofort\nGreift das Ziel sofort an und verursacht 4 Schaden. Zusätzlich werden die nächsten erfolgreichen 0 Nahkampfangriffe 1,5% der maximalen Gesundheit wiederherstellen. Dieser Effekt hält bis Abbruch lang an. Schaden basiert auf Angriffskraft." }
