entries[60019] = { ["name"] = "Donnerknall", ["text"] = "Sofort 6 sek. Abklingzeit\nTrifft Gegner in der Nähe, erhöht die Zeit zwischen ihren Angriffen 30 Sek. lang um 20% und verursacht 6 Schaden. Schaden wird durch Angriffskraft erhöht. Diese Fähigkeit verursacht zusätzliche Bedrohung und wirkt auf maximal 4 Ziele." }
