entries[60023] = { ["name"] = "Geißelbanneraura", ["text"] = "Sofort\nErhöht bei allen Schergen der Geißel im Umkreis von 50 Metern den verursachten Schaden um 20% und das Angriffstempo um 10%." }
entries[60024] = { ["name"] = "Violetter Protodrache", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren violetten Protodrachen oder gibt ihn wieder frei. Das ist ein Flugreittier.\n\"Ich frage mich immer wieder, ob die Dinge sich nicht anders entwickelt hätten, wenn die Titanen auch nur einen weiteren Drachenschwarm erhoben hätten. - Alexstrasza\"\nErfolg:\nWas für eine lange, seltsame Reise...\nKategorie:\nWeltereignisse" }
entries[60025] = { ["name"] = "Albinodrache", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren Albinodrachen oder gibt ihn wieder frei. Das ist ein Flugreittier.\n\"Selbst die Versuche der Gesellschaft für einheimische Drachen haben keine klaren Erkenntnisse darüber gebracht, ob der Albinodrache mit einem der bekannten Drachenschwärme verwandt ist. - Breanni\"\nErfolg:\nFühren der Kavallerie\nKategorie:\nAllgemein" }
