entries[60396] = { ["name"] = "Quecksilbriger Alchemistenstein", ["text"] = "Wirken in 3 sek.\nReagenzien:\nGoldklee (20), Äonenleben (2), Frostlotus\nBerufsausbilder:\nAlchemie von Nordend (25)\nKosten:\n1\n\nQuecksilbriger Alchemistenstein\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Alchemistenstein (1)Schmuck\n+3 Intelligenz\nErhöht Eure Tempowertung um + 4.\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\n28\nBenötigt Alchemie von Nordend\n(25)\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"" }
entries[60403] = { ["name"] = "Unzerstörbarer Alchemistenstein", ["text"] = "Wirken in 3 sek.\nReagenzien:\nBrennnessel (20), Pygmäenöl (12), Frostlotus\nBerufsausbilder:\nAlchemie von Nordend (25)\nKosten:\n1\n\nUnzerstörbarer Alchemistenstein\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Alchemistenstein (1)Schmuck\n+4 Ausdauer\n+ 4 Ausweichen\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\n28\nBenötigt Alchemie von Nordend\n(25)\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"" }
