entries[60405] = { ["name"] = "Mächtiger Alchemistenstein", ["text"] = "Wirken in 2 sek.\nReagenzien:\nSchlangenzunge (15), Tigerlilie (15), Frostlotus\nBerufsausbilder:\nAlchemie von Nordend (25)\nKosten:\n1\n\nMächtiger Alchemistenstein\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Alchemistenstein (1)Schmuck\n+2 [Beweglichkeit oder Stärke] Erhöht Eure kritische Trefferwertung um + 3.\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\n28\nBenötigt Alchemie von Nordend\n(25)\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"" }
